char* findShortestUniquePrefix(TrieNode* root, const char* word) {
    TrieNode* curr = root;
    static char prefix[MAX_WORD_LEN]; // Static buffer for result
    int prefix_len = 0;
    int len = strlen(word);

    for (int i = 0; i < len; i++) {
        int index = word[i] - 'a';
        curr = curr->children[index];
        prefix[prefix_len++] = word[i];
        prefix[prefix_len] = '\0'; // Null-terminate current prefix
        if (curr->count == 1) {
            return strdup(prefix); // Return a dynamically allocated copy
        }
    }
    return strdup(prefix); // Should not be reached if all words have unique prefixes
}

