import java.util.*;

public class Solution {
    static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean end = false;
    }

    static class Trie {
        TrieNode root = new TrieNode();

        void insert(String word) {
            TrieNode node = root;
            for (char c : word.toCharArray()) {
                int idx = c - 'a';
                if (node.children[idx] == null) node.children[idx] = new TrieNode();
                node = node.children[idx];
            }
            node.end = true;
        }

        boolean search(String word) {
            TrieNode node = find(word);
            return node != null && node.end;
        }

        boolean startsWith(String prefix) {
            return find(prefix) != null;
        }

        private TrieNode find(String s) {
            TrieNode node = root;
            for (char c : s.toCharArray()) {
                int idx = c - 'a';
                if (node.children[idx] == null) return null;
                node = node.children[idx];
            }
            return node;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextLine()) return;
        String opsLine = sc.nextLine().trim();
        if (!sc.hasNextLine()) return;
        String argsLine = sc.nextLine().trim();

        List<String> ops = parseStringList(opsLine);
        List<List<String>> argsList = parseNestedStringList(argsLine);

        Trie trie = null;
        List<String> res = new ArrayList<>();

        for (int i = 0; i < ops.size(); i++) {
            String op = ops.get(i);
            List<String> opArgs = argsList.get(i);

            if (op.equals("Trie")) {
                trie = new Trie();
                res.add("null");
            } else if (op.equals("insert")) {
                trie.insert(opArgs.get(0));
                res.add("null");
            } else if (op.equals("search")) {
                res.add(String.valueOf(trie.search(opArgs.get(0))));
            } else if (op.equals("startsWith")) {
                res.add(String.valueOf(trie.startsWith(opArgs.get(0))));
            }
        }
        System.out.println("[" + String.join(", ", res) + "]");
    }

    private static List<String> parseStringList(String s) {
        List<String> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1); // remove outer []
        boolean inQuote = false;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '"') { inQuote = !inQuote; }
            else if (c == ',' && !inQuote) {
                res.add(sb.toString().trim());
                sb.setLength(0);
            } else {
                sb.append(c);
            }
        }
        if (sb.length() > 0) res.add(sb.toString().trim());
        return res;
    }

    private static List<List<String>> parseNestedStringList(String s) {
        List<List<String>> res = new ArrayList<>();
        s = s.substring(1, s.length() - 1); // remove outer []
        int depth = 0;
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == '[') {
                depth++;
                if (depth > 1) sb.append(c);
            } else if (c == ']') {
                depth--;
                if (depth > 0) sb.append(c);
                else {
                    List<String> sub = new ArrayList<>();
                    String content = sb.toString().trim();
                    if (!content.isEmpty()) {
                        for (String item : content.split(",")) {
                            sub.add(item.trim().replace("\"", ""));
                        }
                    }
                    res.add(sub);
                    sb.setLength(0);
                }
            } else if (c == ',' && depth == 0) {
                // skip commas between sublists
            } else if (depth > 0) {
                sb.append(c);
            }
        }
        return res;
    }
}

