    next_node = node.children[char]
    if next_node.word:
        res.add(next_node.word)

    board[r][c] = '#'
    for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols: dfs(nr, nc, next_node)
    board[r][c] = char

